def second_largest(nums: list) -> int:
    """Return the second largest distinct value; raise ValueError if there is none."""
    if not nums:
        raise ValueError("List is empty, no second largest.")
    # Use a set to get distinct values
    distinct = set(nums)
    if len(distinct) < 2:
        raise ValueError("Not enough distinct elements for second largest.")
    # Remove the largest then take max of remaining
    largest = max(distinct)
    distinct.remove(largest)
    return max(distinct)
